brand_css_dark:
:root {
  /* Primary - Wanted Blue (다크 semantic: normal=blue 60, strong=blue 55, heavy=blue 50) */
  --color-primary-50:  #001536;  /* blue 10 · 선택 배경 */
  --color-primary-100: #002966;  /* blue 20 */
  --color-primary-200: #003E9C;  /* blue 30 */
  --color-primary-300: #0054D1;  /* blue 40 */
  --color-primary-400: #0066FF;  /* blue 50 · primary heavy (pressed) */
  --color-primary-500: #3385FF;  /* blue 60 · primary normal (기본) */
  --color-primary-600: #1A75FF;  /* blue 55 · primary strong (hover) */
  --color-primary-700: #0066FF;  /* blue 50 · primary heavy */
  --color-primary-800: #9EC5FF;  /* blue 80 · 어두운 면 위 강조 글자 */
  --color-primary-900: #C9DEFE;  /* blue 90 */

  /* Secondary - inverse 배경 (다크에서는 흰색) */
  --color-secondary-500: #FFFFFF;

  /* Neutral - Cool Neutral (반전) */
  --color-neutral-0:    #0F0F10;  /* coolNeutral 5 · background alternative */
  --color-neutral-50:   #1B1C1E;  /* coolNeutral 15 · background normal */
  --color-neutral-100:  #2E2F33;  /* coolNeutral 22 · interaction disable */
  --color-neutral-200:  #37383C;  /* coolNeutral 25 · line solid normal */
  --color-neutral-300:  #46474C;  /* coolNeutral 30 */
  --color-neutral-500:  #70737C;  /* coolNeutral 50 · 라인·채움의 기준색 */
  --color-neutral-700:  #AEB0B6;  /* coolNeutral 80 · 라벨 투명도 기준색 */
  --color-neutral-900:  #F7F7F8;  /* coolNeutral 99 · label normal */
  --color-neutral-1000: #FFFFFF;

  /* Semantic - 다크는 한 단계 밝은 60 */
  --color-success-bg: rgba(30,212,90,0.08);
  --color-success-fg: #1ED45A;   /* green 60 */
  --color-warning-bg: rgba(255,169,56,0.08);
  --color-warning-fg: #FFA938;   /* orange 60 */
  --color-error-bg:   rgba(255,99,99,0.08);
  --color-error-fg:   #FF6363;   /* red 60 */
  --color-info-bg:    rgba(51,133,255,0.12);
  --color-info-fg:    #69A5FF;

  /* Surface */
  --bg-base:     #1B1C1E;               /* background normal */
  --bg-subtle:   #0F0F10;               /* background alternative */
  --bg-elevated: #212225;               /* elevated normal · 카드 */
  --bg-overlay:  rgba(23,23,25,0.74);   /* material dimmer */

  /* Text - label 위계 */
  --text-primary:    #F7F7F8;                 /* label normal */
  --text-secondary:  rgba(194,196,200,0.88);  /* label neutral */
  --text-tertiary:   rgba(174,176,182,0.61);  /* label alternative */
  --text-on-primary: #FFFFFF;
  --text-disabled:   rgba(152,155,162,0.16);  /* label disable */
  --text-assistive:  rgba(174,176,182,0.28);  /* label assistive */

  /* Border */
  --border-default: rgba(112,115,124,0.32);  /* line normal normal */
  --border-subtle:  rgba(112,115,124,0.22);  /* line normal alternative */
  --border-strong:  rgba(112,115,124,0.52);  /* (추정) */
  --border-focus:   #3385FF;
  --border-solid:   #37383C;                 /* line solid normal */

  /* Fill */
  --fill-normal:      rgba(112,115,124,0.22);
  --fill-strong:      rgba(112,115,124,0.28);
  --fill-alternative: rgba(112,115,124,0.12);
}

[data-theme="light"] {
  /* Primary - Wanted Blue (atomic blue 95 → 20) */
  --color-primary-50:  #EAF2FE;  /* blue 95 · 선택 배경, info 면 */
  --color-primary-100: #C9DEFE;  /* blue 90 */
  --color-primary-200: #9EC5FF;  /* blue 80 */
  --color-primary-300: #69A5FF;  /* blue 70 */
  --color-primary-400: #3385FF;  /* blue 60 · 다크 모드 primary normal */
  --color-primary-500: #0066FF;  /* blue 50 · primary normal (기본) */
  --color-primary-600: #005EEB;  /* blue 45 · primary strong (hover) */
  --color-primary-700: #0054D1;  /* blue 40 · primary heavy (pressed) */
  --color-primary-800: #003E9C;  /* blue 30 */
  --color-primary-900: #002966;  /* blue 20 */

  /* Secondary - inverse 배경 (토스트·툴팁) */
  --color-secondary-500: #1B1C1E; /* coolNeutral 15 */

  /* Neutral - Cool Neutral */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #F7F7F8;  /* coolNeutral 99 · background alternative */
  --color-neutral-100:  #F4F4F5;  /* coolNeutral 98 · interaction disable */
  --color-neutral-200:  #E1E2E4;  /* coolNeutral 96 · line solid normal */
  --color-neutral-300:  #C2C4C8;  /* coolNeutral 90 */
  --color-neutral-500:  #70737C;  /* coolNeutral 50 · 라인·채움의 기준색 */
  --color-neutral-700:  #37383C;  /* coolNeutral 25 · 라벨 투명도 기준색 */
  --color-neutral-900:  #171719;  /* coolNeutral 10 · label normal */
  --color-neutral-1000: #000000;

  /* Semantic - status 는 원색, 배경은 같은 색 8% */
  --color-success-bg: rgba(0,191,64,0.08);
  --color-success-fg: #00BF40;   /* green 50 · positive */
  --color-warning-bg: rgba(255,146,0,0.08);
  --color-warning-fg: #FF9200;   /* orange 50 · cautionary */
  --color-error-bg:   rgba(255,66,66,0.08);
  --color-error-fg:   #FF4242;   /* red 50 · negative */
  --color-info-bg:    #EAF2FE;
  --color-info-fg:    #0066FF;

  /* Surface */
  --bg-base:     #FFFFFF;               /* background normal */
  --bg-subtle:   #F7F7F8;               /* background alternative · 섹션 구분 */
  --bg-elevated: #FFFFFF;               /* elevated normal · 카드 */
  --bg-overlay:  rgba(23,23,25,0.52);   /* material dimmer */

  /* Text - label 위계 (회색 + 투명도) */
  --text-primary:    #171719;               /* label normal */
  --text-secondary:  rgba(46,47,51,0.88);   /* label neutral */
  --text-tertiary:   rgba(55,56,60,0.61);   /* label alternative */
  --text-on-primary: #FFFFFF;               /* static white */
  --text-disabled:   rgba(55,56,60,0.16);   /* label disable */
  --text-assistive:  rgba(55,56,60,0.28);   /* label assistive · placeholder */

  /* Border - line (투명) + solid */
  --border-default: rgba(112,115,124,0.22); /* line normal normal */
  --border-subtle:  rgba(112,115,124,0.08); /* line normal alternative */
  --border-strong:  rgba(112,115,124,0.43); /* (추정) 강조 라인 */
  --border-focus:   #0066FF;
  --border-solid:   #E1E2E4;                /* line solid normal */

  /* Fill - 칩·아이콘 버튼 바탕 */
  --fill-normal:      rgba(112,115,124,0.08);
  --fill-strong:      rgba(112,115,124,0.16);
  --fill-alternative: rgba(112,115,124,0.05);
}


:root {
  --radius-none: 0;
  --radius-sm: 6px;    /* 배지 (추정) */
  --radius-md: 8px;    /* small 버튼 · 칩 */
  --radius-lg: 12px;   /* large 버튼 · 카드 · 입력창 */
  --radius-xl: 16px;   /* 바텀시트 · 모달 (추정) */
  --radius-full: 9999px;
}

:root {
  --shadow-none: none;
  --shadow-xs: 0 1px 2px -1px rgba(23,23,23,0.10);                                                  /* 카드 기본 */
  --shadow-sm: 0 2px 4px -2px rgba(23,23,23,0.06), 0 4px 6px -1px rgba(23,23,23,0.06);             /* 카드 hover · 칩 */
  --shadow-md: 0 4px 6px -2px rgba(23,23,23,0.07), 0 10px 15px -3px rgba(23,23,23,0.07);           /* 드롭다운 · 팝오버 */
  --shadow-lg: 0 6px 10px -4px rgba(23,23,23,0.08), 0 16px 24px -6px rgba(23,23,23,0.08);          /* 모달 */
  --shadow-xl: 0 10px 15px -5px rgba(23,23,23,0.10), 0 24px 38px -10px rgba(23,23,23,0.12);        /* 풀스크린 다이얼로그 */
  --shadow-spread: 0 15px 75px 0 rgba(23,23,23,0.16);                                               /* 넓게 퍼지는 플로팅 레이어 */
}

.btn {
  font: 600 16px/24px Pretendard, -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', sans-serif;
  letter-spacing: 0.0057em;
  border: 0; cursor: pointer;
  border-radius: var(--radius-lg);
  padding: 12px 28px;                       /* large */
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  transition: background-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out);
}
.btn-md { padding: 9px 20px; border-radius: 10px; font-size: 15px; line-height: 22px; }
.btn-sm { padding: 7px 14px; border-radius: var(--radius-md); font-size: 13px; line-height: 18px; }

/* Primary (solid) */
.btn-primary { background: var(--color-primary-500); color: var(--text-on-primary); }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-primary:active { background: var(--color-primary-700); }
.btn-primary:disabled { background: var(--color-neutral-100); color: var(--text-disabled); cursor: not-allowed; }
.btn-primary.is-loading { color: transparent; position: relative; }

/* Secondary (outlined) */
.btn-secondary { background: transparent; color: var(--color-primary-500); box-shadow: inset 0 0 0 1px var(--border-default); }
.btn-secondary:hover { background: var(--fill-alternative); }
.btn-secondary:active { background: var(--fill-normal); }
.btn-secondary:disabled { color: var(--text-disabled); }

/* Ghost (assistive · medium 굵기) */
.btn-ghost { background: transparent; color: var(--text-secondary); font-weight: 500; box-shadow: inset 0 0 0 1px var(--border-default); }
.btn-ghost:hover { background: var(--fill-alternative); }
.btn-ghost:active { background: var(--fill-normal); }

/* Danger */
.btn-danger { background: var(--color-error-fg); color: #FFFFFF; }
.btn-danger:hover { filter: brightness(0.94); }
.btn-danger:disabled { background: var(--color-neutral-100); color: var(--text-disabled); }
.input {
  width: 100%; box-sizing: border-box;
  font: 400 16px/24px Pretendard, -apple-system, sans-serif;
  padding: 12px; border: 0; border-radius: var(--radius-lg);
  background: var(--bg-elevated); color: var(--text-primary);
  box-shadow: inset 0 0 0 1px var(--border-default);
  transition: box-shadow var(--duration-base) ease;
}
.input::placeholder { color: var(--text-assistive); }
.input:focus { outline: none; box-shadow: inset 0 0 0 2px var(--border-focus); }
.input.is-error { box-shadow: inset 0 0 0 2px var(--color-error-fg); }
.input:disabled { background: var(--color-neutral-100); color: var(--text-disabled); }
.card {
  border-radius: var(--radius-lg); padding: 12px;
  background: var(--bg-elevated);
  box-shadow: var(--shadow-xs), inset 0 0 0 1px var(--border-subtle);
}
.card-emphasis { background: var(--color-primary-50); box-shadow: inset 0 0 0 1px rgba(0,102,255,0.28); }
.card-outlined { background: transparent; box-shadow: inset 0 0 0 1px var(--border-default); }
.badge { display: inline-flex; align-items: center; gap: 2px; padding: 2px 6px; border-radius: var(--radius-sm); font: 600 12px/16px Pretendard, sans-serif; letter-spacing: 0.0252em; }
.badge-solid   { background: var(--color-primary-500); color: #FFFFFF; }
.badge-subtle  { background: var(--fill-normal); color: var(--text-secondary); }
.badge-outline { box-shadow: inset 0 0 0 1px var(--border-default); color: var(--text-tertiary); }
.badge-positive { background: var(--color-success-bg); color: #00A13A; }
.gnb {
  height: 62px; display: flex; align-items: center; gap: 24px; padding: 0 20px;
  background: var(--bg-base); border-bottom: 1px solid var(--border-subtle);
}
.gnb-logo { display: flex; align-items: center; color: var(--text-primary); }
.gnb-link { font: 600 15px/22px Pretendard, sans-serif; color: var(--text-primary); text-decoration: none; }
.gnb-link[aria-current="page"] { color: var(--color-primary-500); }
.gnb-chip { padding: 7px 14px; border-radius: var(--radius-md); font: 500 13px/18px Pretendard, sans-serif; box-shadow: inset 0 0 0 1px var(--border-default); color: var(--text-tertiary); }
.gnb-chip.is-active { background: var(--text-primary); color: var(--bg-base); box-shadow: none; font-weight: 600; }

:root {
  --duration-fast: 150ms;
  --duration-base: 200ms;   /* 입력창 테두리 전환 ease 0.2s (공식) */
  --duration-slow: 300ms;
  --ease-out: cubic-bezier(0.2, 0, 0, 1);         /* (추정) */
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);    /* (추정) */
}
